{
  "message": "Migrated user validation and serialization to Pydantic v2 while preserving dependency pins.",
  "rationale": "ConfigDict enables attribute and mapping validation, accepts field names and aliases, and forbids extra mapping fields. model_validate coerces valid string IDs and rejects missing or invalid fields; model_dump(by_alias=True) outputs id and displayName.",
  "files": [
    {
      "path": "src/integration.py",
      "content": "from pydantic import BaseModel, ConfigDict, Field


class UserView(BaseModel):
    model_config = ConfigDict(
        from_attributes=True,
        populate_by_name=True,
        extra="forbid",
    )

    id: int
    display_name: str = Field(alias="displayName")


def serialize_user(value):
    return UserView.model_validate(value).model_dump(by_alias=True)
